extern "c" fn uws_res_write_header_int(ssl: i32, res: *uws_res, key: [*]const u8, key_length: usize, value: u64) callconv(.c) void;

extern "c" fn uws_res_end_without_body(ssl: i32, res: *uws_res, close_connection: bool) callconv(.c) void;

extern "c" fn uws_res_end_sendfile(ssl: i32, res: *uws_res, write_offset: u64, close_connection: bool) callconv(.c) void;

extern "c" fn uws_res_timeout(ssl: i32, res: *uws_res, timeout: u8) callconv(.c) void;

extern "c" fn uws_res_reset_timeout(ssl: i32, res: *uws_res) callconv(.c) void;

extern "c" fn uws_res_get_buffered_amount(ssl: i32, res: *uws_res) callconv(.c) u64;

extern "c" fn uws_res_write(ssl: i32, res: *uws_res, data: ?[*]const u8, length: *usize) callconv(.c) bool;

extern "c" fn uws_res_get_write_offset(ssl: i32, res: *uws_res) callconv(.c) u64;

extern "c" fn uws_res_override_write_offset(ssl: i32, res: *uws_res, off: u64) callconv(.c) void;

extern "c" fn uws_res_has_responded(ssl: i32, res: *uws_res) callconv(.c) bool;

extern "c" fn uws_res_on_writable(ssl: i32, res: *uws_res, handler: ResWritableHandler, user_data: ?*anyopaque) callconv(.c) void;

extern "c" fn uws_res_clear_on_writable(ssl: i32, res: *uws_res) callconv(.c) void;

extern "c" fn uws_res_on_aborted(ssl: i32, res: *uws_res, handler: ResVoidHandler, optional_data: ?*anyopaque) callconv(.c) void;

extern "c" fn uws_res_on_timeout(ssl: i32, res: *uws_res, handler: ResVoidHandler, optional_data: ?*anyopaque) callconv(.c) void;

extern "c" fn uws_res_try_end(ssl: i32, res: *uws_res, data: ?[*]const u8, length: usize, total: usize, close: bool) callconv(.c) bool;

extern "c" fn uws_res_end_stream(ssl: i32, res: *uws_res, close_connection: bool) callconv(.c) void;

extern "c" fn uws_res_prepare_for_sendfile(ssl: i32, res: *uws_res) callconv(.c) void;

extern "c" fn uws_res_get_native_handle(ssl: i32, res: *uws_res) callconv(.c) *bun.uws.Socket;

extern "c" fn uws_res_get_remote_address_as_text(ssl: i32, res: *uws_res, dest: *[*]const u8) callconv(.c) usize;

extern "c" fn uws_res_on_data(ssl: i32, res: *uws_res, handler: ResDataHandler, optional_data: ?*anyopaque) callconv(.c) void;

extern "c" fn uws_res_upgrade(ssl: i32, res: *uws_res, data: ?*anyopaque, key: [*c]const u8, kl: usize, proto: [*c]const u8, pl: usize, ext: [*c]const u8, el: usize, ws: ?*bun.uws.WebSocketUpgradeContext) callconv(.c) *bun.uws.Socket;

extern "c" fn uws_res_cork(ssl: i32, res: *uws_res, ctx: ?*anyopaque, corker: ResCorkHandler) callconv(.c) void;

pub fn NewResponse(comptime ssl_flag: i32) type {
        return struct {

pub inline fn castRes(res: *uws_res) *@This() {
            return bun.cast((&@This()), res);
    }

pub inline fn downcast(self: *@This()) *uws_res {
            return bun.cast(*uws_res, self);
    }

pub inline fn downcastSocket(self: *@This()) *bun.uws.us_socket_t {
            return (blk: {
            break :blk @as(*bun.uws.us_socket_t, @alignCast(@ptrCast(self)));

});
    }

pub fn end(self: *@This(), data: []const u8, close_connection: bool) void {
            _ = uws_res_end(ssl_flag, self.downcast(), data.ptr, data.len, close_connection);
    }

pub fn tryEnd(self: *@This(), data: []const u8, total: usize, close_: bool) bool {
            return uws_res_try_end(ssl_flag, self.downcast(), data.ptr, data.len, total, close_);
    }

pub fn getSocketData(self: *@This()) ?*anyopaque {
            return uws_res_get_socket_data(ssl_flag, self.downcast());
    }

pub fn isConnectRequest(self: *@This()) bool {
            return uws_res_is_connect_request(ssl_flag, self.downcast());
    }

pub fn flushHeaders(self: *@This(), flushImmediately: bool) void {
            _ = uws_res_flush_headers(ssl_flag, self.downcast(), flushImmediately);
    }

pub fn isCorked(self: *@This()) bool {
            return uws_res_is_corked(ssl_flag, self.downcast());
    }

pub fn state(self: *@This()) State {
            return uws_res_state(ssl_flag, self.downcast());
    }

pub fn shouldCloseConnection(self: *@This()) bool {
            return self.state().isHttpConnectionClose();
    }

pub fn isClosed(self: *@This()) bool {
            return self.downcastSocket().isClosed();
    }

pub fn prepareForSendfile(self: *@This()) void {
            _ = uws_res_prepare_for_sendfile(ssl_flag, self.downcast());
    }

pub fn uncork(self: *@This()) void {
            _ = uws_res_uncork(ssl_flag, self.downcast());
    }

pub fn pause(self: *@This()) void {
            _ = uws_res_pause(ssl_flag, self.downcast());
    }

pub fn resumeResponse(self: *@This()) void {
            _ = uws_res_resume(ssl_flag, self.downcast());
    }

pub fn writeContinue(self: *@This()) void {
            _ = uws_res_write_continue(ssl_flag, self.downcast());
    }

pub fn writeStatus(self: *@This(), status: []const u8) void {
            _ = uws_res_write_status(ssl_flag, self.downcast(), status.ptr, status.len);
    }

pub fn writeHeader(self: *@This(), key: []const u8, value: []const u8) void {
            _ = uws_res_write_header(ssl_flag, self.downcast(), key.ptr, key.len, value.ptr, value.len);
    }

pub fn writeHeaderInt(self: *@This(), key: []const u8, value: u64) void {
            _ = uws_res_write_header_int(ssl_flag, self.downcast(), key.ptr, key.len, value);
    }

pub fn endWithoutBody(self: *@This(), close_connection: bool) void {
            _ = uws_res_end_without_body(ssl_flag, self.downcast(), close_connection);
    }

pub fn endSendFile(self: *@This(), write_offset: u64, close_connection: bool) void {
            _ = uws_res_end_sendfile(ssl_flag, self.downcast(), write_offset, close_connection);
    }

pub fn timeout(self: *@This(), seconds: u8) void {
            _ = uws_res_timeout(ssl_flag, self.downcast(), seconds);
    }

pub fn resetTimeout(self: *@This()) void {
            _ = uws_res_reset_timeout(ssl_flag, self.downcast());
    }

pub fn getBufferedAmount(self: *@This()) u64 {
            return uws_res_get_buffered_amount(ssl_flag, self.downcast());
    }

pub fn write(self: *@This(), data: []const u8) WriteResult {
            var len: usize = data.len;
            _ = &len;
            return (if (uws_res_write(ssl_flag, self.downcast(), data.ptr, (&len))) WriteResult{ .want_more = len } else WriteResult{ .backpressure = len });
    }

pub fn writeBuffer(self: *@This(), data: []const u8) WriteResult {
            return self.write(data);
    }

pub fn getWriteOffset(self: *@This()) u64 {
            return uws_res_get_write_offset(ssl_flag, self.downcast());
    }

pub fn overrideWriteOffset(self: *@This(), offset: u64) void {
            _ = uws_res_override_write_offset(ssl_flag, self.downcast(), offset);
    }

pub fn hasResponded(self: *@This()) bool {
            return uws_res_has_responded(ssl_flag, self.downcast());
    }

pub fn onWritable(self: *@This(), ud: anytype, comptime handler: anytype) void {
            {
                _ = uws_res_on_writable(ssl_flag, self.downcast(), ResOnWritableWrap(SelfPtr, handler).callback, @ptrCast(ud));
            }
    }

pub fn clearOnWritable(self: *@This()) void {
            _ = uws_res_clear_on_writable(ssl_flag, self.downcast());
    }

pub fn onAborted(self: *@This(), ud: anytype, comptime handler: anytype) void {
            {
                _ = uws_res_on_aborted(ssl_flag, self.downcast(), ResCbWrap(SelfPtr, handler).callback, @ptrCast(ud));
            }
    }

pub fn clearAborted(self: *@This()) void {
            _ = uws_res_on_aborted(ssl_flag, self.downcast(), null, null);
    }

pub fn onTimeout(self: *@This(), ud: anytype, comptime handler: anytype) void {
            {
                _ = uws_res_on_timeout(ssl_flag, self.downcast(), ResCbWrap(SelfPtr, handler).callback, @ptrCast(ud));
            }
    }

pub fn clearTimeout(self: *@This()) void {
            _ = uws_res_on_timeout(ssl_flag, self.downcast(), null, null);
    }

pub fn onData(self: *@This(), ud: anytype, comptime handler: anytype) void {
            {
                _ = uws_res_on_data(ssl_flag, self.downcast(), ResOnDataWrap(SelfPtr, handler).callback, @ptrCast(ud));
            }
    }

pub fn clearOnData(self: *@This()) void {
            _ = uws_res_on_data(ssl_flag, self.downcast(), null, null);
    }

pub fn getRemoteAddressAsText(self: *@This()) ?[]const u8 {
            var buf: [*]const u8 = undefined;
            _ = &buf;
            const size = uws_res_get_remote_address_as_text(ssl_flag, self.downcast(), (&buf));
            return (if ((size > 0)) (blk: {
            break :blk buf[0..size];

}) else null);
    }

pub fn getRemoteAddress(self: *@This(), dest: []u8) ?[]const u8 {
            var ptr: [*c]const u8 = undefined;
            _ = &ptr;
            var port: i32 = undefined;
            _ = &port;
            var is_ipv6: bool = undefined;
            _ = &is_ipv6;
            const len = uws_res_get_remote_address_info(self.downcast(), (&ptr), (&port), (&is_ipv6));
            if ((len == 0)) {
                return null;
            }
            const slice = (blk: {
            break :blk ptr[0..len];

});
            if ((slice.len > dest.len)) {
                return null;
            }
            _ = bun.copy(u8, dest, slice);
            return dest[0..slice.len];
    }

pub fn getRemoteSocketInfo(self: *@This()) ?bun.uws.SocketAddress {
            var address = bun.uws.SocketAddress{ .ip = undefined, .port = undefined, .is_ipv6 = undefined };
            _ = &address;
            const len = uws_res_get_remote_address_info(self.downcast(), (&address.ip.ptr), (&address.port), (&address.is_ipv6));
            if ((len > 0)) {
                address.ip.len = len;
                return address;
            }
            return null;
    }

pub fn getNativeHandle(self: *@This()) bun.FD {
            const handle = uws_res_get_native_handle(ssl_flag, self.downcast());
            if (comptime bun.Environment.isWindows) {
                return (blk: {
                break :blk bun.FD.fromNative(@ptrCast(handle));

});
            }
            return (blk: {
            break :blk bun.FD.fromNative(@intCast(@intFromPtr(handle)));

});
    }

pub fn corked(self: *@This(), comptime handler: anytype, args_tuple: std.meta.ArgsTuple(@TypeOf(handler))) void {
            {
                _ = uws_res_cork(ssl_flag, self.downcast(), @ptrCast(@constCast((&args_tuple))), ResCorkedWrap(handler, @TypeOf(args_tuple)).handle);
            }
    }

pub fn runCorkedWithType(self: *@This(), ud: anytype, comptime handler: anytype) void {
            {
                _ = uws_res_cork(ssl_flag, self.downcast(), @ptrCast(ud), ResRunCorkedWrap(handler).onCork);
            }
    }

pub fn upgrade(self: *@This(), comptime Data: type, data: Data, sec_web_socket_key: []const u8, sec_web_socket_protocol: []const u8, sec_web_socket_extensions: []const u8, ctx: ?*bun.uws.WebSocketUpgradeContext) *bun.uws.Socket {
            return uws_res_upgrade(ssl_flag, self.downcast(), data, sec_web_socket_key.ptr, sec_web_socket_key.len, sec_web_socket_protocol.ptr, sec_web_socket_protocol.len, sec_web_socket_extensions.ptr, sec_web_socket_extensions.len, ctx);
    }

pub fn endStream(self: *@This(), close_connection: bool) void {
            _ = uws_res_end_stream(ssl_flag, self.downcast(), close_connection);
    }

pub fn writeMark(self: *@This()) void {
            _ = uws_res_write_mark(ssl_flag, self.downcast());
    }

pub fn markWroteContentLengthHeader(self: *@This()) void {
            _ = uws_res_mark_wrote_content_length_header(ssl_flag, self.downcast());
    }

pub fn markNeedsMore(self: *@This()) void {
            if ((ssl_flag == 0)) {
                _ = us_socket_mark_needs_more_not_ssl(self.downcast());
            }
    }
    const SelfPtr = *@This();
};
}

pub fn ResOnWritableWrap(comptime SelfPtr: type, comptime handler: anytype) type {
        return struct {

pub fn callback(res_: *uws_res, offset: u64, user_data: ?*anyopaque) callconv(.c) bool {
            {
                return handler(@ptrCast(@alignCast(user_data)), offset, bun.cast(SelfPtr, res_));
            }
    }
};
}

pub fn ResCbWrap(comptime SelfPtr: type, comptime handler: anytype) type {
        return struct {

pub fn callback(res_: *uws_res, user_data: ?*anyopaque) callconv(.c) void {
            {
                _ = handler(@ptrCast(@alignCast(user_data)), bun.cast(SelfPtr, res_));
            }
    }
};
}

pub fn ResOnDataWrap(comptime SelfPtr: type, comptime handler: anytype) type {
        return struct {

pub fn callback(res_: *uws_res, data: [*c]const u8, length: usize, last: bool, user_data: ?*anyopaque) callconv(.c) void {
            {
                const slice: []const u8 = (if ((length > 0)) data[0..length] else "");
                _ = handler(@ptrCast(@alignCast(user_data)), bun.cast(SelfPtr, res_), slice, last);
            }
    }
};
}

pub fn ResCorkedWrap(comptime handler: anytype, comptime ArgsType: type) type {
        return struct {

pub fn handle(user_data: ?*anyopaque) callconv(.c) void {
            {
                const args: *ArgsType = @ptrCast(@alignCast(user_data.?));
                _ = @call(bun.callmod_inline, handler_fn, args.*);
            }
    }
    const handler_fn = handler;
};
}

pub fn ResRunCorkedWrap(comptime handler: anytype) type {
        return struct {

pub fn onCork(user_data: ?*anyopaque) callconv(.c) void {
            {
                _ = handler(@ptrCast(@alignCast(user_data)));
            }
    }
};
}

pub fn AnyResOnDataWrap(comptime UserDataType: type, comptime handler: anytype) type {
        return struct {

pub fn ssl_cb(user_data: UserDataType, _: *ResponseTLS, data: []const u8, last: bool) void {
            _ = @call(bun.callmod_inline, handler, .{ user_data, data, last });
    }

pub fn tcp_cb(user_data: UserDataType, _: *ResponseTCP, data: []const u8, last: bool) void {
            _ = @call(bun.callmod_inline, handler, .{ user_data, data, last });
    }

pub fn h3_cb(user_data: UserDataType, _: *H3Response, data: []const u8, last: bool) void {
            _ = @call(bun.callmod_inline, handler, .{ user_data, data, last });
    }
};
}

pub fn AnyResOnWritableWrap(comptime UserDataType: type, comptime handler: anytype) type {
        return struct {

pub fn ssl_cb(user_data: UserDataType, offset: u64, resp: *ResponseTLS) bool {
            return handler(user_data, offset, AnyResponse{ .SSL = resp });
    }

pub fn tcp_cb(user_data: UserDataType, offset: u64, resp: *ResponseTCP) bool {
            return handler(user_data, offset, AnyResponse{ .TCP = resp });
    }

pub fn h3_cb(user_data: UserDataType, offset: u64, resp: *H3Response) bool {
            return handler(user_data, offset, AnyResponse{ .H3 = resp });
    }
};
}

pub fn AnyResCbWrap(comptime UserDataType: type, comptime handler: anytype) type {
        return struct {

pub fn ssl_cb(user_data: UserDataType, resp: *ResponseTLS) void {
            _ = handler(user_data, AnyResponse{ .SSL = resp });
    }

pub fn tcp_cb(user_data: UserDataType, resp: *ResponseTCP) void {
            _ = handler(user_data, AnyResponse{ .TCP = resp });
    }

pub fn h3_cb(user_data: UserDataType, resp: *H3Response) void {
            _ = handler(user_data, AnyResponse{ .H3 = resp });
    }
};
}
